package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.StringUtils;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for StringUtils.indexOfAny(String, String[])
 * Designed to maximize branch and line coverage.
 */
public class StringUtils_indexOfAny_TriageGen2Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAny_NullSearchStrs() {
        // Covers: if (searchStrs == null) return INDEX_NOT_FOUND;
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", null));
    }

    @Test
    public void testIndexOfAny_EmptySearchStrs() {
        // Covers: sz = searchStrs.length; loop doesn't execute; returns INDEX_NOT_FOUND
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", new String[]{}));
    }

    @Test
    public void testIndexOfAny_NoMatch() {
        // Covers: if (tmp == INDEX_NOT_FOUND) continue; 
        // Returns INDEX_NOT_FOUND because ret remains Integer.MAX_VALUE
        String[] searchStrs = {"xyz", "123"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_WithNullElementInArray() {
        // Covers: if (search == null) continue;
        String[] searchStrs = {null, "b"};
        assertEquals(1, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_SingleMatch() {
        // Covers: basic success path
        String[] searchStrs = {"bc"};
        assertEquals(1, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsFirstOccurrence() {
        // Covers: if (tmp < ret) ret = tmp;
        // "b" is at index 1, "a" is at index 0. Should return 0.
        String[] searchStrs = {"b", "a"};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MultipleMatches_ReturnsEarliestIndex() {
        // "ba" is index 0, "c" is index 2. Should return 0.
        String[] searchStrs = {"c", "ba"};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_AllElementsNull() {
        // Covers: loop runs, but all continue due to null or not found
        String[] searchStrs = {null, null};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_MatchAtEnd() {
        String[] searchStrs = {"c"};
        assertEquals(2, StringUtils.indexOfAny("abc", searchStrs));
    }

    @Test
    public void testIndexOfAny_EmptyStringSource() {
        // str.indexOf will return -1 for any non-empty searchStr in an empty str
        String[] searchStrs = {"a"};
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAny("", searchStrs));
    }

    @Test
    public void testIndexOfAny_EmptySearchString() {
        // str.indexOf("") returns 0 in Java
        String[] searchStrs = {""};
        assertEquals(0, StringUtils.indexOfAny("abc", searchStrs));
    }
}
